#!/usr/bin/env bash
# GENERATED by bun run scripts/extract-upstream-steps.ts — do not edit by hand.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"
PIN="1672852136fc87748249d22bce0819f33419ea79"
actual="$(git -C upstream rev-parse HEAD)"
if [[ "$actual" != "$PIN" ]]; then
  echo "upstream pin mismatch: $actual" >&2
  exit 1
fi

if ! command -v docker >/dev/null 2>&1 || ! docker info >/dev/null 2>&1; then
  echo "docker not available; run upstream jobs via GitHub Actions .github/workflows/upstream-ci.yml" >&2
  exit 1
fi

INNER_TEST="$(mktemp)"
