cat > "$INNER_TEST" <<'EOF_TEST'
#!/usr/bin/env bash
set -euo pipefail
git config --global --replace-all safe.directory '*'

echo '==> Verify generated provider presets'
(
  go run ./internal/llm/gen -check -output extensions/frontend/src/shared/providers.generated.ts -kotlin-output extensions/idea/src/main/kotlin/com/alibaba/opencodereview/idea/services/ProviderNames.generated.kt
)

echo '==> Verify license headers'
(
  bash scripts/verify-license.sh
)

echo '==> Verify action pins'
(
  bash scripts/verify-action-pins.sh
)

echo '==> Verify sources contain no unapproved non-English text'
(
  go run scripts/verify-english-only.go
)

echo '==> Check formatting'
(
  unformatted="$(gofmt -s -l .)"
  if [ -n "$unformatted" ]; then
    echo "::error::Not gofmt-clean. Run 'gofmt -s -w .' and commit:"
    echo "$unformatted"
    gofmt -s -d .
    exit 1
  fi
  
)

echo '==> Check line endings'
(
  git add --renormalize .
  if ! git diff --cached --quiet; then
    echo "::error::Line endings must be LF. Run 'git add --renormalize .' and commit the diff below."
    git diff --cached --stat
    exit 1
  fi
  
)

echo '==> Check go.mod is tidy'
(
  go mod tidy
  if ! git diff --exit-code -- go.mod go.sum; then
    echo "::error::go.mod/go.sum are not tidy. Run 'go mod tidy' and commit the diff above."
    exit 1
  fi
  
)

echo '==> Vet'
(
  go vet ./...
)

echo '==> Govulncheck'
(
  go install golang.org/x/vuln/cmd/govulncheck@v1.6.0
  govulncheck ./...
  
)

echo '==> Test with coverage'
export OCR_DELEGATE_REQUIRE_PTY='1'
(
  go test -v -race -count=1 -coverprofile=coverage.out ./...
  go tool cover -func=coverage.out | grep total: | awk '{print $3}'
  
)

echo '==> Check coverage threshold'
(
  COVERAGE=$(go tool cover -func=coverage.out | grep total: | awk '{print $3}' | sed 's/%//')
  echo "Total coverage: ${COVERAGE}%"
  if awk "BEGIN {exit !($COVERAGE < 90)}"; then
    echo "FAIL: Coverage ${COVERAGE}% is below 90% threshold"
    exit 1
  fi
  echo "PASS: Coverage ${COVERAGE}% meets 90% threshold"
  
)

echo '==> Build'
(
  go build -o ./opencodereview ./cmd/opencodereview
)

echo '==> Smoke test'
(
  ./opencodereview --version
  ./opencodereview --version | grep -q "open-code-review"
  HELP=$(./opencodereview --help)
  echo "$HELP" | grep -q "Commands:"
  echo "$HELP" | grep -q "review"
  echo "$HELP" | grep -q "scan"
  echo "$HELP" | grep -q "delegate"
  echo "$HELP" | grep -q "config"
  echo "$HELP" | grep -q "auth"
  echo "$HELP" | grep -q "llm"
  echo "$HELP" | grep -q "viewer"
  echo "$HELP" | grep -q "session"
  echo "$HELP" | grep -q "rules"
  rm -f ./opencodereview
  
)

EOF_TEST

echo "==== job: test (docker golang:1.26.9) ===="
docker run --rm --cpus=2 -v "$ROOT:/w" -v "$INNER_TEST:/tmp/run-test.sh:ro" -w /w/upstream golang:1.26.9 bash /tmp/run-test.sh

